//! 🧪️ Original carrier allocation boundary agrees with independent protobuf framing.
use super::*;
use std::{sync::atomic::{AtomicUsize,Ordering},io::Write,process::{Command,Stdio}};
fn neutral()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
fn grant()->semio_framework_value::RetainedCloneGrant{serde_json::from_value(neutral()["partialReceiving"]["receivingGrant"].clone()).unwrap()}
fn decode_wire(bytes:&[u8],control:&mut NativeDecodeControl<'_>,grant:semio_framework_value::RetainedCloneGrant)->Result<DocumentArchivePack,ValueError>{decode_document_archive_bytes_controlled(bytes,&mut crate::os_store::NativeSnapshotDecodeOwner::new(control,grant))}

#[test]
fn original_composed_carrier_reservations_match_independent_protobuf_and_preserve_refusal(){
 let law=neutral();let grant=grant();let wire:Vec<u8>=serde_json::from_value(law["wire"].clone()).unwrap();let pointer=wire.as_ptr();let owned=AtomicUsize::new(0);let calls=AtomicUsize::new(0);let maximum=law["maximumBytes"].as_u64().unwrap()as usize;let mut allocation=|request:semio_framework_value::native_decoding::NativeDecodeAllocation|{assert_eq!(request.owned_bytes,owned.load(Ordering::Relaxed));assert_eq!(request.next_owned_bytes,request.owned_bytes+request.bytes);owned.store(request.next_owned_bytes,Ordering::Relaxed);calls.fetch_add(1,Ordering::Relaxed);Ok(())};let mut progress=|_|true;let mut recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();let mut control=NativeDecodeControl::new_forwarded(maximum,&mut progress,&mut allocation);control.install_retirement_recipient(&mut recipient).unwrap();let archive=decode_wire(&wire,&mut control,grant).unwrap();let reference=|r:&DocumentArchiveArtifactRef|serde_json::json!({"artifactId":r.artifact_id,"artifactKind":r.artifact_kind,"standard":r.standard,"subset":r.subset});let actual=serde_json::json!({"parentPack":archive.parent_pack,"parentSpr":archive.parent_spr,"members":archive.members.iter().map(|m|serde_json::json!({"ordinal":m.ordinal,"reference":reference(&m.reference),"owner":{"parent":reference(&m.owner.parent),"slot":m.owner.slot,"childId":m.owner.child_id},"envelopePack":m.envelope_pack})).collect::<Vec<_>>()});assert_eq!(actual,law["expected"]);assert_eq!(control.owned_bytes(),owned.load(Ordering::Relaxed));assert!(calls.load(Ordering::Relaxed)>14);assert_eq!(wire.as_ptr(),pointer);
 let script="import pb from 'protobufjs/minimal';const input=JSON.parse(await Bun.stdin.text());const r=pb.Reader.create(Uint8Array.from(input));if(r.buf[r.pos++]!==1)throw Error('version');const reference=()=>({artifactId:r.string(),artifactKind:r.string(),standard:r.string(),subset:r.string()});const output={parentPack:Array.from(r.bytes()),parentSpr:Array.from(r.bytes()),members:[]};const count=r.uint32();for(let i=0;i<count;i++)output.members.push({ordinal:r.uint32(),reference:reference(),owner:{parent:reference(),slot:r.string(),childId:r.string()},envelopePack:Array.from(r.bytes())});if(r.pos!==r.len)throw Error('trailing');await Bun.write(Bun.stdout,JSON.stringify(output));";let mut child=Command::new("bun").args(["-e",script]).current_dir(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).ancestors().find(|path|path.join("package.json").is_file()&&path.join("🧰️framework").is_dir()).unwrap().to_path_buf()).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(law["wire"].to_string().as_bytes()).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));assert_eq!(actual,serde_json::from_slice::<serde_json::Value>(&output.stdout).unwrap());
 for kind in [ValueRefusalKind::OwnershipLimit,ValueRefusalKind::Canceled]{let calls=AtomicUsize::new(0);let mut allocation=|_:semio_framework_value::native_decoding::NativeDecodeAllocation|{calls.fetch_add(1,Ordering::Relaxed);Err(ValueError::literal(kind,"original composed carrier allocation refused"))};let mut progress=|_|true;let mut recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();let mut control=NativeDecodeControl::new_forwarded(maximum,&mut progress,&mut allocation);control.install_retirement_recipient(&mut recipient).unwrap();assert_eq!(decode_wire(&wire,&mut control,grant).unwrap_err().kind,kind);assert_eq!(control.owned_bytes(),0);assert_eq!(calls.load(Ordering::Relaxed),1);assert_eq!(wire.as_ptr(),pointer);}
 for malformed in law["refused"].as_array().unwrap(){let bytes:Vec<u8>=serde_json::from_value(malformed.clone()).unwrap();let mut progress=|_|true;let mut recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();let mut control=NativeDecodeControl::new(maximum,&mut progress);control.install_retirement_recipient(&mut recipient).unwrap();assert!(decode_wire(&bytes,&mut control,grant).is_err());while control.has_retirement_owner(){control.close_retirement_recipient(grant).unwrap();}}
 println!("[DEBUG] Actual composed carrier receiving: nativeFields=14 receivingFrameAdmitted=true originalBeforeEveryReserve=true exactCumulativeLedger=true refusalKinds=2 zeroOwnedOnInitialRefusal=true independentProtobufjs=true sourcePointerPreserved=true malformedCases=4");
}

#[test]
fn archive_partial_field_refusals_preserve_original_recipient_until_admitted_physical_drain(){
 use semio_framework_value::native_decoding::{NativeDecodeRetirementRecipient,NativeDecodeAllocation};
 let neutral=neutral();let receiving=&neutral["partialReceiving"];let grant:semio_framework_value::RetainedCloneGrant=serde_json::from_value(receiving["receivingGrant"].clone()).unwrap();
 for malformed in [false,true]{
  let wire:Vec<u8>=serde_json::from_value(if malformed{receiving["trailingWire"].clone()}else{neutral["wire"].clone()}).unwrap();let pointer=wire.as_ptr();let mut recipient=NativeDecodeRetirementRecipient::new();let calls=AtomicUsize::new(0);let ledger=AtomicUsize::new(0);let mut allocation=|request:NativeDecodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(Ordering::Relaxed));let call=calls.fetch_add(1,Ordering::Relaxed)+1;if !malformed&&call==receiving["failAllocation"].as_u64().unwrap()as usize{return Err(ValueError::literal(ValueRefusalKind::Canceled,"archive original interior allocation refusal"))}ledger.store(request.next_owned_bytes,Ordering::Relaxed);Ok(())};let mut progress=|_|true;let mut control=NativeDecodeControl::new_forwarded(neutral["maximumBytes"].as_u64().unwrap()as usize,&mut progress,&mut allocation);control.install_retirement_recipient(&mut recipient).unwrap();
  let (result,owned,released)=crate::test_allocation::observe_backing(||decode_wire(&wire,&mut control,grant));assert!(result.is_err());assert!(owned>0);assert_eq!(released,0);assert!(control.has_retirement_owner());let retained=control.owned_bytes();let mut zero=grant;zero.maximum_release_bytes=0;let _=control.close_retirement_recipient(zero);assert!(control.has_retirement_owner());while control.has_retirement_owner(){control.close_retirement_recipient(grant).unwrap();assert_eq!(control.owned_bytes(),ledger.load(Ordering::Relaxed));}assert!(control.owned_bytes()>=retained);drop(control);assert!(!recipient.has_owner());assert_eq!(wire.as_ptr(),pointer);println!("[DEBUG] Composed archive partial receiving malformed={} retainedOriginalOwner=true noOrdinaryDrop=true originalPortDuringDrain=true originalGrant=true sourcePointer=true",malformed);
 }
}

#[test]
fn archive_interior_utf8_cancel_retains_materialized_prefix_and_head_history_before_publication(){
 use semio_framework_value::native_decoding::{NativeDecodeRetirementRecipient,NativeDecodeAllocation};
 let law=neutral();let receiving=&law["partialReceiving"];let interior=&receiving["interiorUtf8"];let text=interior["literal"].as_str().unwrap().repeat(interior["copies"].as_u64().unwrap()as usize);let mut wire=vec![DOCUMENT_ARCHIVE_VERSION,0,0,1,7];let mut length=text.len();loop{let low=(length&127)as u8;length>>=7;wire.push(low|if length==0{0}else{128});if length==0{break}}wire.extend_from_slice(text.as_bytes());wire.extend_from_slice(&[0;10]);let pointer=wire.as_ptr();let grant=grant();let mut recipient=NativeDecodeRetirementRecipient::new();let ledger=AtomicUsize::new(0);let mut allocation=|request:NativeDecodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(Ordering::Relaxed));ledger.store(request.next_owned_bytes,Ordering::Relaxed);Ok(())};let observed=AtomicUsize::new(0);let mut progress=|event:semio_framework_value::native_decoding::NativeDecodeProgress|{if event.total==text.len()&&event.owned_bytes>=text.len()&&event.completed>=interior["refuseAtCompleted"].as_u64().unwrap()as usize{observed.store(event.completed,Ordering::Relaxed);false}else{true}};let mut native=NativeDecodeControl::new_forwarded(interior["maximumNativeBytes"].as_u64().unwrap()as usize,&mut progress,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let(result,owned,released)=crate::test_allocation::observe_backing(||decode_wire(&wire,&mut native,grant));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::Canceled);assert!(owned>=text.len());assert_eq!(released,0);assert_eq!(observed.load(Ordering::Relaxed),interior["refuseAtCompleted"].as_u64().unwrap()as usize);assert!(native.has_retirement_owner());while native.has_retirement_owner(){native.close_retirement_recipient(grant).unwrap();assert_eq!(native.owned_bytes(),ledger.load(Ordering::Relaxed));}drop(native);assert!(!recipient.has_owner());assert_eq!(wire.as_ptr(),pointer);
 let wire:Vec<u8>=serde_json::from_value(receiving["historyHeadWire"].clone()).unwrap();let mut recipient=NativeDecodeRetirementRecipient::new();let mut progress=|_|true;let mut native=NativeDecodeControl::new(law["maximumBytes"].as_u64().unwrap()as usize,&mut progress);native.install_retirement_recipient(&mut recipient).unwrap();let(result,owned,released)=crate::test_allocation::observe_backing(||decode_document_archive_head_controlled(&wire,&mut crate::os_store::NativeSnapshotDecodeOwner::new(&mut native,grant)));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::InvalidValue);assert!(owned>0);assert_eq!(released,0);assert!(native.has_retirement_owner());while native.has_retirement_owner(){native.close_retirement_recipient(grant).unwrap();}drop(native);assert!(!recipient.has_owner());println!("[DEBUG] Original archive receiving UTF8Completed=65535 partialCapacityRetained=true noOrdinaryRelease=true samePortDrain=true headHistoryRefusedBeforePublication=true");
}

#[test]
fn archive_body_receiving_retains_partial_on_independent_original_undergrants(){
 let law=neutral();let original=grant();let wire:Vec<u8>=serde_json::from_value(law["wire"].clone()).unwrap();let pointer=wire.as_ptr();
 for currency in law["partialReceiving"]["bodyRefusals"].as_array().unwrap(){
  let mut caller=original;match currency.as_str().unwrap(){"copy"=>caller.maximum_copy_bytes=0,"capacity"=>caller.maximum_capacity_bytes=0,"depth"=>caller.maximum_depth=2,_=>unreachable!()}
  let mut recipient=semio_framework_value::native_decoding::NativeDecodeRetirementRecipient::new();let mut progress=|_|true;let mut native=NativeDecodeControl::new(law["maximumBytes"].as_u64().unwrap()as usize,&mut progress);native.install_retirement_recipient(&mut recipient).unwrap();
  let (result,born,released)=crate::test_allocation::observe_backing(||{let mut owner=crate::os_store::NativeSnapshotDecodeOwner::new(&mut native,caller);let result=decode_document_archive_bytes_controlled(&wire,&mut owner);(result,owner.progress())});
  assert!(result.0.is_err());assert!(result.1.fits(caller));assert_eq!(result.1.retained_capacity_bytes,born);assert_eq!(result.1.released_bytes,released);assert_eq!(released,0);if currency=="capacity"{assert_eq!(born,0);assert!(!native.has_retirement_owner());}else{assert!(born>0);assert!(native.has_retirement_owner());}
  while native.has_retirement_owner(){native.close_retirement_recipient(original).unwrap();}drop(native);assert!(!recipient.has_owner());assert_eq!(wire.as_ptr(),pointer);
  println!("[DEBUG] Archive original body currency={} zeroUnfundedPayloadBirth=true retainedPartial=true exactAcceptedCapacity={} release={} sameSourcePointer=true",currency,born,released);
 }
}
